package ama.transcript;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.zip.*;
class OfficeTranscriptParserTest {
 private static final UUID FILE=UUID.fromString("00000000-0000-4000-8000-000000000001");
 private static final TranscriptDocumentParser.ParseBudget LIMIT=new TranscriptDocumentParser.ParseBudget(32*1024*1024,1024*1024,4096);
 private static byte[] fixture(String ext)throws Exception{try(var in=OfficeTranscriptParserTest.class.getResourceAsStream("/ama/transcript/fixtures/meeting."+ext)){return Objects.requireNonNull(in).readAllBytes();}}
 private static String hash(byte[] bytes)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}
 @Test void genuineOfficeAndPdfDocumentsHaveOriginalHashOrderedTextAndStableSourceIds()throws Exception{for(String ext:List.of("doc","docx","pdf","pptx","txt")){byte[] bytes=fixture(ext);var parser=new OfficeTranscriptParser();var first=parser.parseMeasured(new ByteArrayInputStream(bytes),FILE,hash(bytes),LIMIT,()->false);var second=parser.parseMeasured(new ByteArrayInputStream(bytes),FILE,hash(bytes),LIMIT,()->false);String text=String.join("\n",first.result().segments().stream().map(TranscriptDocumentParser.Segment::text).toList());assertTrue(text.contains("会议导入验证"),ext+" "+text);assertTrue(text.contains("严格按原型复刻"),ext);assertTrue(text.indexOf("会议导入验证")<text.indexOf("严格按原型复刻"),ext);assertEquals(hash(bytes),first.result().sourceSha256());assertEquals(bytes.length,first.usage().sourceBytes());assertEquals(first.result(),second.result());assertEquals(OfficeTranscriptParser.PROFILE_VERSION,first.result().parserProfileVersion());assertTrue(first.result().segments().stream().allMatch(s->s.sourceFileId().equals(FILE)&&s.speakerId()==null&&s.startMs()==null&&s.endMs()==null));}}
 @Test void sourceHashAndEachBudgetAreEnforcedBeforeReturningAnyResult()throws Exception{for(String ext:List.of("doc","docx","pdf","pptx")){var bytes=fixture(ext);var parser=new OfficeTranscriptParser();assertEquals(TranscriptDocumentParser.ErrorCode.SOURCE_HASH_MISMATCH,assertThrows(TranscriptDocumentParser.ParseException.class,()->parser.parse(new ByteArrayInputStream(bytes),FILE,"0".repeat(64),LIMIT,()->false)).code());assertEquals(TranscriptDocumentParser.ErrorCode.SOURCE_BYTES_EXCEEDED,assertThrows(TranscriptDocumentParser.ParseException.class,()->parser.parse(new ByteArrayInputStream(bytes),FILE,hash(bytes),new TranscriptDocumentParser.ParseBudget(bytes.length-1,100000,100),()->false)).code());assertEquals(TranscriptDocumentParser.ErrorCode.UTF16_CODE_UNITS_EXCEEDED,assertThrows(TranscriptDocumentParser.ParseException.class,()->parser.parse(new ByteArrayInputStream(bytes),FILE,hash(bytes),new TranscriptDocumentParser.ParseBudget(bytes.length,4,100),()->false)).code());assertEquals(TranscriptDocumentParser.ErrorCode.SEGMENTS_EXCEEDED,assertThrows(TranscriptDocumentParser.ParseException.class,()->parser.parse(new ByteArrayInputStream(bytes),FILE,hash(bytes),new TranscriptDocumentParser.ParseBudget(bytes.length,100000,1),()->false)).code());}}
 @Test void cancellationCorruptEmptyAndExternalEntitiesFailClosed()throws Exception{var parser=new OfficeTranscriptParser();byte[] pdf="%PDF-1.7\nbroken".getBytes(StandardCharsets.UTF_8);assertThrows(TranscriptDocumentParser.ParseException.class,()->parser.parse(new ByteArrayInputStream(pdf),FILE,hash(pdf),LIMIT,()->false));byte[] doc=fixture("doc");assertEquals(TranscriptDocumentParser.ErrorCode.CANCELLED,assertThrows(TranscriptDocumentParser.ParseException.class,()->parser.parse(new ByteArrayInputStream(doc),FILE,hash(doc),LIMIT,()->true)).code());var out=new ByteArrayOutputStream();try(var zip=new ZipOutputStream(out)){zip.putNextEntry(new ZipEntry("word/document.xml"));zip.write("<!DOCTYPE x [<!ENTITY secret SYSTEM 'file:///etc/passwd'>]><w:document xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:p><w:t>&secret;</w:t></w:p></w:document>".getBytes(StandardCharsets.UTF_8));zip.closeEntry();}var xml=out.toByteArray();assertThrows(TranscriptDocumentParser.ParseException.class,()->parser.parse(new ByteArrayInputStream(xml),FILE,hash(xml),LIMIT,()->false));byte[] empty=new byte[0];assertEquals(TranscriptDocumentParser.ErrorCode.NO_TEXT,assertThrows(TranscriptDocumentParser.ParseException.class,()->parser.parse(new ByteArrayInputStream(empty),FILE,hash(empty),LIMIT,()->false)).code());}
 @Test void callerOwnsSourceAndUtf8LegacyBehaviorIsRetained()throws Exception{boolean[] closed={false};byte[] bytes=fixture("txt");var input=new ByteArrayInputStream(bytes){public void close(){closed[0]=true;}};var result=new OfficeTranscriptParser().parse(input,FILE,hash(bytes),LIMIT,()->false);assertFalse(closed[0]);assertEquals(3,result.segments().size());}
}
